-- Audited supplier and raw-material master maintenance.
create or replace function public.create_factory_supplier(p_code text,p_name text,p_type text default null,p_contact text default null,p_phone text default null,p_notes text default null)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if not has_factory_role(auth.uid(),array['admin','purchase'])then raise exception'not authorized';end if;if nullif(trim(p_code),'')is null or nullif(trim(p_name),'')is null then raise exception'code and name are required';end if;insert into suppliers(supplier_code,supplier_name,supplier_type,contact_person,contact_phone,notes,created_by)values(upper(trim(p_code)),trim(p_name),nullif(trim(p_type),''),nullif(trim(p_contact),''),nullif(trim(p_phone),''),nullif(trim(p_notes),''),auth.uid()::text)returning supplier_id into v_id;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Supplier Created','suppliers',v_id,jsonb_build_object('supplier_code',upper(trim(p_code)),'supplier_name',trim(p_name)));return v_id;end$$;
create or replace function public.create_factory_material(p_code text,p_name text,p_category text,p_uom uuid,p_lot_control boolean default false,p_notes text default null)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if not has_factory_role(auth.uid(),array['admin','purchase'])then raise exception'not authorized';end if;if nullif(trim(p_code),'')is null or nullif(trim(p_name),'')is null or nullif(trim(p_category),'')is null then raise exception'code, name and category are required';end if;if not exists(select 1 from uoms where uom_id=p_uom)then raise exception'invalid unit';end if;insert into materials(material_code,material_name,material_category,primary_uom,lot_control_required,notes,created_by)values(upper(trim(p_code)),trim(p_name),upper(trim(p_category)),p_uom,coalesce(p_lot_control,false),nullif(trim(p_notes),''),auth.uid()::text)returning material_id into v_id;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Material Created','materials',v_id,jsonb_build_object('material_code',upper(trim(p_code)),'material_name',trim(p_name),'category',upper(trim(p_category)),'lot_control',coalesce(p_lot_control,false)));return v_id;end$$;
revoke all on function public.create_factory_supplier(text,text,text,text,text,text)from public;revoke all on function public.create_factory_material(text,text,text,uuid,boolean,text)from public;
grant execute on function public.create_factory_supplier(text,text,text,text,text,text)to authenticated;grant execute on function public.create_factory_material(text,text,text,uuid,boolean,text)to authenticated;
